<script lang="ts">
  import { getContent, saveContent, site, type Athlete, type Plan } from '$lib/content';
  let authenticated = $state(false), password = $state(''), notice = $state('');
  let data = $state(structuredClone(site));
  const login = () => { authenticated = password === 'MATHIEU'; notice = authenticated ? 'Local editor unlocked.' : 'Try the demo passcode: MATHIEU'; };
  const save = () => { saveContent(data); notice = 'Saved in this browser. Export a copy before changing devices.'; };
  const reset = () => { localStorage.removeItem('mathieu-content'); data = structuredClone(site); notice = 'Reset to the starter content.'; };
  const exportData = () => { const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'mathieu-coaching-content.json'; a.click(); URL.revokeObjectURL(url); };
  const addAthlete = () => data.athletes.push({ name: 'New athlete', event: 'Event', before: '—', after: '—', delta: 'New', quote: 'Add their quote here.', focus: 'Training focus' } as Athlete);
  const addPlan = () => data.plans.push({ name: 'New plan', price: 'R0', cadence: 'per month', summary: 'Describe the plan.', included: ['First inclusion'] } as Plan);
  $effect(() => { if (authenticated) data = structuredClone(getContent()); });
</script>
<svelte:head><title>Admin / Mathieu Coaching</title></svelte:head>
{#if !authenticated}<section class="gate"><span class="eyebrow">Local admin / demo only</span><h1>KEEP THE<br /><em>WORK</em><br />MOVING.</h1><p>This is a browser-local editor for the starter site. It is not secure authentication and should be replaced with Supabase Auth before inviting real admins.</p><form onsubmit={(e) => { e.preventDefault(); login(); }}><input type="password" bind:value={password} placeholder="Demo passcode" /><button class="button solid">Unlock editor ↗</button></form>{#if notice}<small>{notice}</small>{/if}</section>{:else}<section class="admin"><div class="admin-head"><span class="eyebrow">Editing local content</span><h1>THE<br />WORKBENCH.</h1><p>Changes save to this browser only. The eventual Supabase tables can follow these same content groups.</p><div class="actions"><button class="button solid" onclick={save}>Save local changes</button><button class="button" onclick={exportData}>Export JSON</button><button class="text" onclick={reset}>Reset starter content</button></div>{#if notice}<small>{notice}</small>{/if}</div><div class="editor"><section><h2>Site basics</h2><label>Coach name<input bind:value={data.coachName} /></label><label>Contact email<input bind:value={data.email} /></label><label>Location<input bind:value={data.location} /></label><label>Home introduction<textarea bind:value={data.intro}></textarea></label></section><section><div class="section-row"><h2>Athlete stories</h2><button class="text" onclick={addAthlete}>+ Add athlete</button></div>{#each data.athletes as athlete, i}<details open><summary>{i + 1}. {athlete.name}</summary><label>Name<input bind:value={athlete.name} /></label><label>Event<input bind:value={athlete.event} /></label><div class="pair"><label>Before<input bind:value={athlete.before} /></label><label>After<input bind:value={athlete.after} /></label></div><label>Improvement<label><input bind:value={athlete.delta} /></label></label><label>Focus<input bind:value={athlete.focus} /></label><label>Quote<textarea bind:value={athlete.quote}></textarea></label><button class="text danger" onclick={() => data.athletes.splice(i, 1)}>Remove athlete</button></details>{/each}</section><section><div class="section-row"><h2>Plans & prices</h2><button class="text" onclick={addPlan}>+ Add plan</button></div>{#each data.plans as plan, i}<details open><summary>{plan.name}</summary><label>Plan name<input bind:value={plan.name} /></label><div class="pair"><label>Price<input bind:value={plan.price} /></label><label>Cadence<input bind:value={plan.cadence} /></label></div><label>Summary<textarea bind:value={plan.summary}></textarea></label><label>Included (one item per line)<textarea value={plan.included.join('\n')} oninput={(e) => plan.included = e.currentTarget.value.split('\n').filter(Boolean)}></textarea></label><button class="text danger" onclick={() => data.plans.splice(i, 1)}>Remove plan</button></details>{/each}</section></div></section>{/if}
<style>.gate,.admin{background:var(--paper);color:var(--ink);min-height:calc(100vh - 75px);padding:clamp(3rem,8vw,8rem)}.gate{max-width:none}.gate h1,.admin h1{font:clamp(4.5rem,11vw,10rem)/.7 var(--display);letter-spacing:-.07em;margin:1rem 0 2rem}.gate em{color:#7a9759;font-style:normal}.gate p,.admin-head p{line-height:1.5;max-width:510px}.gate form{display:flex;gap:.8rem;margin:2rem 0}.gate input{background:none;border:0;border-bottom:1px solid #65715a;font:1rem var(--mono);outline:0;padding:.7rem 0}.gate small,.admin small{font:.7rem var(--mono)}.admin{display:grid;gap:5rem;grid-template-columns:.7fr 1.3fr}.admin h1{font-size:clamp(3.5rem,7vw,7rem)}.actions{display:flex;flex-wrap:wrap;gap:.6rem;margin:2rem 0}.button{background:none}.text{background:none;border:0;color:var(--ink);cursor:pointer;font:.68rem var(--mono);letter-spacing:.06em;padding:.7rem 0;text-decoration:underline;text-transform:uppercase}.editor{display:grid;gap:1.4rem}.editor section{border:1px solid #aeb5a7;padding:1.25rem}.editor h2{font:1.6rem var(--display);margin:0 0 1rem}.section-row{align-items:center;display:flex;justify-content:space-between}.editor label{display:grid;font:.63rem var(--mono);gap:.35rem;letter-spacing:.08em;margin:.7rem 0;text-transform:uppercase}.editor input,.editor textarea{background:#f8f9f5;border:1px solid #aeb5a7;font:1rem Arial;padding:.6rem;resize:vertical}.editor textarea{min-height:60px}.pair{display:grid;gap:.7rem;grid-template-columns:1fr 1fr}.editor details{border-top:1px solid #b2b8ab;margin-top:1rem;padding-top:.7rem}.editor summary{cursor:pointer;font:.75rem var(--mono);font-weight:bold;text-transform:uppercase}.danger{color:#8d3a30}@media(max-width:800px){.admin{grid-template-columns:1fr;gap:2rem}.gate h1{font-size:5rem}.gate form{align-items:flex-start;flex-direction:column}.pair{grid-template-columns:1fr}}</style>
